CREATE TABLE municipios (
    municipio_id INT AUTO_INCREMENT PRIMARY KEY,
    nombre VARCHAR(100) NOT NULL,
    departamento VARCHAR(100)
);

CREATE TABLE tipos_ganado (
    tipo_id INT AUTO_INCREMENT PRIMARY KEY,
    nombre_tipo VARCHAR(50),
    descripcion VARCHAR(150)
);

CREATE TABLE veterinarios (
    veterinario_id INT AUTO_INCREMENT PRIMARY KEY,
    nombre VARCHAR(100),
    telefono VARCHAR(20),
    especialidad VARCHAR(100)
);

CREATE TABLE vacunas (
    vacuna_id INT AUTO_INCREMENT PRIMARY KEY,
    nombre VARCHAR(100),
    descripcion VARCHAR(150),
    dosis VARCHAR(50)
);

CREATE TABLE alimentos (
    alimento_id INT AUTO_INCREMENT PRIMARY KEY,
    nombre VARCHAR(100),
    tipo VARCHAR(50),
    costo DECIMAL(10,2)
);

CREATE TABLE IF NOT EXISTS bitacora_mantenimiento (
    id_bitacora INT AUTO_INCREMENT PRIMARY KEY,
    evento_nombre VARCHAR(100) NOT NULL,
    filas_purgadas INT NOT NULL,
    fecha_ejecucion DATETIME NOT NULL
);

CREATE FUNCTION fn_CalcularEdadMeses(
    p_ganado_id INT
)
RETURNS INT
DETERMINISTIC
READS SQL DATA
BEGIN

	DECLARE v_fecha_nacimiento DATE;


	SELECT fecha_nacimiento
    INTO v_fecha_nacimiento
    FROM ganado g
    WHERE g.ganado_id = p_ganado_id;

	RETURN TIMESTAMPDIFF(MONTH, v_fecha_nacimiento, CURDATE());


END;

CREATE FUNCTION fn_PromedioPesoPorRaza(
    p_raza VARCHAR(50)
)
RETURNS DECIMAL(10,2)
DETERMINISTIC
READS SQL DATA
BEGIN

	DECLARE v_peso_promedio DECIMAL(10,2) DEFAULT 0.00;

		SELECT AVG(peso)
	    INTO v_peso_promedio
	    FROM ganado g
	    WHERE  g.raza = p_raza;

		RETURN IFNULL(v_peso_promedio, 0.00);
END;

CREATE FUNCTION fn_ContarGanadoPorSocio(
    p_socio_id INT
)
RETURNS INT
DETERMINISTIC
READS SQL DATA
BEGIN

	DECLARE v_cantidad_total_ganado INT DEFAULT 0;

		SELECT COUNT(*)
	    INTO v_cantidad_total_ganado
	    FROM ganado g
	    JOIN fincas f ON g.finca_id = f.finca_id
	    WHERE f.socio_id = p_socio_id;

		RETURN IFNULL(v_cantidad_total_ganado, 0);
END;

CREATE FUNCTION fn_CostoTotalAlimentacion(
    p_ganado_id INT
)
RETURNS DECIMAL(10,2)
DETERMINISTIC
READS SQL DATA
BEGIN

	DECLARE v_costo_alimentos_consumidos DECIMAL(10,2) DEFAULT 0;

		SELECT SUM(a.costo * al.cantidad_kg)
	    INTO v_costo_alimentos_consumidos
	    FROM alimentos a
	    JOIN alimentacion al ON al.alimento_id = a.alimento_id
	    WHERE al.ganado_id = p_ganado_id;

		RETURN IFNULL(v_costo_alimentos_consumidos, 0.00);
END;

CREATE PROCEDURE sp_RegistrarProduccionLeche (
    IN p_codigo_arete VARCHAR(50),
    IN p_fecha DATE,
    IN p_litros DECIMAL(10,2)
)
BEGIN
    DECLARE v_ganado_id INT DEFAULT NULL;
    DECLARE v_nombre_tipo VARCHAR(50);
    DECLARE v_sexo VARCHAR(10);

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    START TRANSACTION;


    SELECT g.ganado_id, tg.nombre_tipo, g.sexo
    INTO v_ganado_id, v_nombre_tipo, v_sexo
    FROM ganado g
    JOIN tipos_ganado tg ON g.tipo_id = tg.tipo_id
    WHERE g.codigo_arete = p_codigo_arete;


    IF v_ganado_id IS NULL THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'No existe un animal con el código de arete indicado.';
    ELSEIF LOWER(v_nombre_tipo) = 'lechero' AND LOWER(v_sexo) = 'hembra' THEN

        INSERT INTO produccion_leche (ganado_id, fecha, litros)
        VALUES (v_ganado_id, p_fecha, p_litros);
    ELSE
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'El animal especificado no corresponde a una hembra lechera.';
    END IF;


    COMMIT;
END;

CREATE PROCEDURE sp_ActualizarSalarioEmpleado (
IN p_empleado_id INT,
IN p_porcentaje DECIMAL(10,2),
OUT p_mensaje VARCHAR(100)
)

BEGIN
	DECLARE v_existe INT;

	DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    START TRANSACTION;

    SELECT COUNT(*) INTO v_existe
    FROM empleados
    WHERE empleado_id = p_empleado_id;

    IF v_existe = 0 THEN
    		SET p_mensaje = 'Error:El empleado no existe';
    	ELSE
    		UPDATE empleados
    		SET salario = salario * ( 1 + (p_porcentaje/100))
    		WHERE empleado_id = p_empleado_id;

    		SET p_mensaje = 'salario actualizado con exito';
    	END IF;

    	COMMIT;

END;

CREATE PROCEDURE sp_TrasladarGanadoFinca (
IN p_ganado_id  INT,
IN p_finca_id INT,
OUT p_mensaje VARCHAR(100)
)

BEGIN

	DECLARE v_existe_ganado INT DEFAULT 0;
    DECLARE v_existe_finca INT DEFAULT 0;

	DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    START TRANSACTION;

    SELECT COUNT(*) INTO v_existe_ganado
    FROM ganado
    WHERE ganado_id = p_ganado_id;

    SELECT COUNT(*) INTO v_existe_finca
    FROM fincas
    WHERE finca_id = p_finca_id;

    IF v_existe_ganado = 0 THEN

        SET p_mensaje = 'Error: El ganado especificado no existe.';
        ROLLBACK;

    ELSEIF v_existe_finca = 0 THEN
        SET p_mensaje = 'Error: La finca de destino no existe.';
        ROLLBACK;
    ELSE


     UPDATE ganado
        SET finca_id = p_finca_id
        WHERE ganado_id = p_ganado_id;

        SET p_mensaje = 'Traslado de ganado realizado con éxito.';
        COMMIT;
    END IF;

END;

CREATE PROCEDURE sp_RegistrarVacunacion (
IN p_codigo_arete VARCHAR(50),
IN p_nombre VARCHAR(100),
IN p_veterinario_id INT,
IN p_observaciones VARCHAR(200),
OUT p_mensaje VARCHAR(100)
)

BEGIN

	DECLARE v_ganado_id INT DEFAULT NULL;
	DECLARE v_vacuna_id INT DEFAULT NULL;

	DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    START TRANSACTION;


    SELECT ganado_id INTO v_ganado_id
    FROM ganado
    WHERE codigo_arete = p_codigo_arete;

    SELECT vacuna_id INTO v_vacuna_id
    FROM vacunas
    WHERE nombre = p_nombre;

    IF v_ganado_id IS NULL THEN

    SET p_mensaje = 'Error: El codigo de arete no existe.';
    ROLLBACK;

    ELSEIF v_vacuna_id IS NULL THEN
        SET p_mensaje = 'Error: La vacuna inggresada no existe.';
        ROLLBACK;
    ELSE

    INSERT INTO vacunacion (ganado_id, vacuna_id, veterinario_id, fecha, observaciones)
    VALUES (v_ganado_id, v_vacuna_id, p_veterinario_id, CURDATE(), p_observaciones);

    SET p_mensaje = 'Vacunacion registrada con exito';
    COMMIT;

    END IF;



END;

CREATE PROCEDURE sp_ReporteGastoAlimento (
    IN p_ganado_id INT,
    IN p_fecha_inicio DATE,
    IN p_fecha_final DATE,
    OUT p_total_gastado DECIMAL(10,2),
    OUT p_mensaje VARCHAR(100)
)
BEGIN
    -- Inicializamos el parámetro de salida por si no hay registros
    SET p_total_gastado = 0.00;

    -- Realizamos el cálculo directo con el JOIN
    SELECT SUM(al.cantidad_kg * a.costo)
    INTO p_total_gastado
    FROM alimentacion al
    JOIN alimentos a ON al.alimento_id = a.alimento_id
    WHERE al.ganado_id = p_ganado_id
      AND al.fecha BETWEEN p_fecha_inicio AND p_fecha_final;

    -- Si el animal existe pero no consumió nada, el SUM da NULL. Lo convertimos a 0.
    IF p_total_gastado IS NULL THEN
        SET p_total_gastado = 0.00;
    END IF;

    SET p_mensaje = 'Reporte generado con exito';

END;

CREATE TRIGGER trg_ValidarPesoGanado_Insert
BEFORE INSERT ON ganado
FOR EACH ROW
BEGIN

    IF NEW.peso <= 0 OR NEW.peso >= 1500.00 THEN

        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Error: El peso ingresado está fuera de los rangos biológicos válidos (1 - 1500 kg)';
    END IF;
END;

CREATE TRIGGER trg_ValidarPesoGanado_Update
BEFORE UPDATE ON ganado
FOR EACH ROW
BEGIN

    IF NEW.peso <= 0 OR NEW.peso >= 1500.00 THEN

        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Error: El peso ingresado está fuera de los rangos biológicos válidos (1 - 1500 kg)';
    END IF;
END;

CREATE TRIGGER trg_ValidarIntervaloVacunacion
BEFORE INSERT ON vacunacion
FOR EACH ROW
BEGIN

    DECLARE v_ultima_fecha DATE;


    SELECT MAX(fecha_aplicacion)
    INTO v_ultima_fecha
    FROM vacunacion
    WHERE ganado_id = NEW.ganado_id
      AND vacuna_id = NEW.vacuna_id;


    IF v_ultima_fecha IS NOT NULL AND DATEDIFF(NEW.fecha_aplicacion, v_ultima_fecha) < 30 THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Error: El animal ya recibió esta vacuna en un periodo menor a 30 días';
    END IF;

END;

CREATE EVENT evt_DepuracionAuditoriaMensual
ON SCHEDULE EVERY 1 MONTH
STARTS CURRENT_TIMESTAMP
DO
BEGIN

    DECLARE v_filas_eliminadas INT DEFAULT 0;

    DELETE FROM auditoria_salarios
    WHERE fecha_modificacion < NOW() - INTERVAL 6 MONTH;


    SET v_filas_eliminadas = ROW_COUNT();

    INSERT INTO bitacora_mantenimiento (evento_nombre, filas_purgadas, fecha_ejecucion)
    VALUES ('evt_DepuracionAuditoriaMensual', v_filas_eliminadas, NOW());

END;

